from pathlib import Path

p=Path('src/components/SettingsModal.tsx')
text=p.read_text()

def rep(old,new,count=1):
    global text
    found=text.count(old)
    if found<count: raise SystemExit(f'Missing SettingsModal anchor: {old[:140]!r} found={found}')
    text=text.replace(old,new,count)

rep("  stampOriginalDataUrl:string; stampRebuiltDataUrl:string; stampMode:AssetMode; activityLogOpen:boolean;\n", "  stampOriginalDataUrl:string; stampRebuiltDataUrl:string; stampMode:AssetMode; activityLogOpen:boolean;\n  dataBackupPin:string; dataRestorePin:string; dataRestoreFile:File|null;\n")
