rep("stampOriginalDataUrl:'',stampRebuiltDataUrl:'',stampMode:'original'},()=>void this.prepareExistingAssets(company,preparationId));", "stampOriginalDataUrl:'',stampRebuiltDataUrl:'',stampMode:'original',dataBackupPin:'',dataRestorePin:'',dataRestoreFile:null},()=>void this.prepareExistingAssets(company,preparationId));")

old="""  private dataCenter():any{return <div className=\"ta-settings-page ta-data-center-page\">{this.pageHeader(t('Data Center','مركز البيانات'),t('Data & activity','البيانات والنشاط'),t('Backup, restore and the encrypted activity log live together here.','النسخ والاستعادة وسجل النشاط المشفر موجودة هنا.'))}{this.card(t('Activity Log','سجل النشاط'),t('Review audited workspace changes without creating a second event system.','راجع تغييرات مساحة العمل المدققة دون إنشاء نظام أحداث ثانٍ.'),<Button icon=\"history\" onClick={()=>this.setState({activityLogOpen:true})}>{t('Open Activity Log','فتح سجل النشاط')}</Button>)}</div>;}\n"""
new="""  private backupFromDataCenter=async()=>{\n    const pin=this.state.dataBackupPin.trim();\n    if(!/^\\d{4,12}$/.test(pin)){this.setState({error:t('Enter your 4–12 digit device PIN to export an encrypted backup.','أدخل رمز PIN للجهاز من 4 إلى 12 رقمًا لتصدير نسخة مشفرة.'),message:''});return;}\n    this.setState({busy:true,error:'',message:''});\n    try{await this.props.onBackup(pin);this.setState({busy:false,dataBackupPin:'',message:t('Encrypted backup exported.','تم تصدير النسخة الاحتياطية المشفرة.')});}\n    catch(e){this.setState({busy:false,error:e instanceof Error?e.message:t('Backup export failed.','فشل تصدير النسخة الاحتياطية.')});}\n  };\n\n  private restoreFromDataCenter=async()=>{\n    const pin=this.state.dataRestorePin.trim(),file=this.state.dataRestoreFile;\n    if(!file){this.setState({error:t('Choose a .lourex-backup file first.','اختر ملف .lourex-backup أولًا.'),message:''});return;}\n    if(!/^\\d{4,12}$/.test(pin)){this.setState({error:t('Enter the PIN used to encrypt this backup.','أدخل رمز PIN المستخدم لتشفير هذه النسخة.'),message:''});return;}\n    this.setState({busy:true,error:'',message:''});\n    try{await this.props.onRestore(file,pin);this.setState({busy:false,dataRestorePin:'',dataRestoreFile:null,message:t('Encrypted backup restored.','تمت استعادة النسخة الاحتياطية المشفرة.')});}\n    catch(e){this.setState({busy:false,error:e instanceof Error?e.message:t('Backup restore failed.','فشلت استعادة النسخة الاحتياطية.')});}\n  };\n\n  private dataCenter():any{\n    const account=this.props.cloudUser;\n    return <div className=\"ta-settings-page ta-data-center-page\">\n      {this.pageHeader(t('Data & Sync','البيانات والمزامنة'),t('Data Center','مركز البيانات'),t('Backup, restore/import, cloud recovery, storage diagnostics and the encrypted activity log live together here.','النسخ والاستعادة/الاستيراد والاستعادة السحابية وتشخيص التخزين وسجل النشاط المشفر موجودة هنا معًا.'))}\n      <div className=\"ta-settings-card-grid ta-data-center-actions-grid\">\n        {this.card(t('Backup / Export','النسخ الاحتياطي / التصدير'),t('Export the full encrypted vault as a portable .lourex-backup file. The device PIN is required for encryption.','صدّر الخزنة المشفرة كاملةً كملف .lourex-backup محمول. يلزم رمز PIN للجهاز للتشفير.'),<div className=\"ta-data-center-action-stack\"><Field label={t('Device PIN','رمز PIN للجهاز')}><Input type=\"password\" inputMode=\"numeric\" autoComplete=\"current-password\" value={this.state.dataBackupPin} onChange={(e:any)=>this.setState({dataBackupPin:e.target.value.replace(/\\D/g,''),error:'',message:''})}/></Field><Button icon=\"download\" variant=\"primary\" disabled={this.state.busy} onClick={()=>void this.backupFromDataCenter()}>{this.state.busy?t('Working…','جارٍ التنفيذ…'):t('Export encrypted backup','تصدير نسخة مشفرة')}</Button></div>)}\n        {this.card(t('Restore / Import','الاستعادة / الاستيراد'),t('Import a LOUREX encrypted backup intentionally. Restore replaces the current local vault after validation.','استورد نسخة LOUREX مشفرة بشكل صريح. تستبدل الاستعادة الخزنة المحلية الحالية بعد التحقق.'),<div className=\"ta-data-center-action-stack\"><Field label={t('Backup file','ملف النسخة')}><input className=\"ta-input\" type=\"file\" accept=\".lourex-backup,application/json\" disabled={this.state.busy} onChange={(e:any)=>this.setState({dataRestoreFile:e.currentTarget.files?.[0]||null,error:'',message:''})}/></Field><Field label={t('Backup PIN','رمز PIN للنسخة')}><Input type=\"password\" inputMode=\"numeric\" autoComplete=\"current-password\" value={this.state.dataRestorePin} onChange={(e:any)=>this.setState({dataRestorePin:e.target.value.replace(/\\D/g,''),error:'',message:''})}/></Field><Button icon=\"upload\" variant=\"primary\" disabled={this.state.busy||!this.state.dataRestoreFile} onClick={()=>void this.restoreFromDataCenter()}>{t('Import & restore backup','استيراد واستعادة النسخة')}</Button></div>)}\n      </div>\n      {this.card(t('Cloud Sync & Recovery','المزامنة والاستعادة السحابية'),account?t('Your authenticated LOUREX account provides the canonical encrypted cloud copy for this workspace.','يوفر حساب LOUREX الموثق النسخة السحابية المشفرة الأساسية لمساحة العمل هذه.'):t('Sign in to a LOUREX account before using encrypted cloud recovery.','سجّل الدخول إلى حساب LOUREX قبل استخدام الاستعادة السحابية المشفرة.'),<div className=\"ta-recovery-status\"><span className={`ta-account-dot ${account?'is-online':'is-offline'}`}/><div><small>{account?t('Cloud account connected','الحساب السحابي متصل'):t('Cloud account required','يتطلب حسابًا سحابيًا')}</small><strong dir=\"ltr\">{account?.email||t('Not signed in','غير مسجل الدخول')}</strong></div>{account?<Button variant=\"secondary\" disabled={this.state.busy} onClick={()=>this.setState({confirmCloudRestore:true,error:'',message:''})}>{t('Restore from Cloud','استرجاع من السحابة')}</Button>:null}</div>)}\n      {this.card(t('Activity Log','سجل النشاط'),t('Review audited workspace changes without creating a second event system.','راجع تغييرات مساحة العمل المدققة دون إنشاء نظام أحداث ثانٍ.'),<Button icon=\"history\" onClick={()=>this.setState({activityLogOpen:true})}>{t('Open Activity Log','فتح سجل النشاط')}</Button>)}\n    </div>;\n  }\n"""
rep(old,new)

